/**
 * BỘ MẪU KIỂM THỬ HỢP NHẤT — 616 câu.
 *
 * Gộp từ hai bộ trước (400 câu phủ rộng + 200 câu đào sâu vào các nhóm đã đo
 * được là yếu). Hai file nguồn đã bị xoá sau khi hợp nhất; đây là nguồn duy
 * nhất từ nay.
 *
 * CẤU TRÚC
 * --------
 *   q         câu hỏi được chấm
 *   history   các lượt hỏi TRƯỚC đó (chỉ phần người dùng). Thiếu = lượt đầu.
 *   group     nhóm, dùng để đọc báo cáo theo từng kiểu câu hỏi
 *   expect    hành vi đúng ở mức ĐẦU-CUỐI: trả lời / từ chối vì thiếu dữ liệu /
 *             hỏi lại vì mơ hồ / không tìm thấy gì
 *   gold      chỉ có ở câu `expect: "answer"`. Điều kiện để một chunk được
 *             tính là CHỨA ĐÁP ÁN — dùng cho các chỉ số truy hồi (Hit@k, MRR,
 *             P@7). Khớp `url` HOẶC `text` là đủ.
 *
 * VÌ SAO `gold` CHẤM THEO NỘI DUNG, KHÔNG THEO MỘT URL DUY NHẤT
 * -------------------------------------------------------------
 * Tra corpus cho thấy đáp án nằm rải nhiều trang: "Đỗ Bá Lâm" có trong 19
 * chunk, "Hackday" trong 40, phần lớn là tin tức chứ không phải trang hồ sơ.
 * Chấm theo một URL sẽ đánh trượt những lượt truy hồi thực ra hoàn toàn đúng.
 * Định nghĩa dùng ở đây là chuẩn của open-domain QA: một chunk tính là ĐÚNG
 * nếu nó thật sự chứa đáp án.
 *
 * So khớp trên `raw`, KHÔNG trên `content`: `content` mang thêm phần header
 * do build-index tự sinh, nên chấm trên đó khiến mọi chunk của một báo cáo đều
 * "chứa" tên báo cáo đó.
 *
 * 207/600 câu có nhãn vàng; các chỉ số truy hồi chỉ tính trên
 * phần này. Câu `not_updated`/`no_answer`/`nothing_found` cố ý KHÔNG có nhãn —
 * với chúng, hành vi đúng là từ chối, và điều đó được đo bằng chỉ số riêng.
 */

export type Expect = "answer" | "not_updated" | "no_answer" | "nothing_found";

export interface Gold {
  /** Nguồn regex, so với `raw` của chunk, không phân biệt hoa thường. */
  text?: string[];
  /** Chuỗi con của URL. */
  url?: string[];
}

export interface Case {
  id: number;
  q: string;
  history?: string[];
  group: string;
  expect: Expect;
  gold?: Gold;
}

