export const GROUPS: string[] = [...new Set(SAMPLES.map((c) => c.group))];

/** Một chunk có chứa đáp án không. Khớp `text` HOẶC `url` là đủ. */
export function isGold(
  chunk: { url?: string; raw?: string; content?: string },
  gold: Gold
): boolean {
  if (gold.url?.some((u) => (chunk.url || "").includes(u))) return true;
  if (!gold.text?.length) return false;
  const hay = chunk.raw || chunk.content || "";
  return gold.text.some((t) => new RegExp(t, "i").test(hay));
}
